  "sections": {
    "SECTION_0_EXEC_SUMMARY": {
      "thesis": "[Judgment] Apple Inc. represents an elite consumer monopoly powered by an active installed base surpassing 2.2 billion devices, unprecedented ecosystem switching costs, and high-margin Services expansion, offset primarily by mature hardware replacement cycles and elevated valuation multiples.",
      "key_findings": [
        "[Fact] TTM Return on Invested Capital (ROIC) stands at 56.2%, driven by asset-light manufacturing and disciplined capital return programs.",
        "[Fact] Upstream forensic indicators show an Altman Z-score of 9.12 (Safe Zone) and Beneish M-score of -2.74, signaling negligible bankruptcy or earnings manipulation risk.",
        "[Derived] Valuation metrics indicate a PEG ratio of 7.42 and an FCF yield of 3.4%, suggesting full to premium pricing relative to near-term earnings growth expectations.",
        "[Interpretation] Services revenue continues to dilute cyclical iPhone hardware exposure, creating structural gross margin accretion above 45%."
      ],
      "recommendation_summary": "[Judgment] Hold / Selective Accumulation on pullbacks; robust quality profile with valuation-constrained total return upside."
    },
    "SECTION_13_IPO_HISTORY": {
      "ipo_date": "1980-12-12",
      "offer_price_split_adjusted": 0.10,
      "narrative": "[Fact] Apple completed its initial public offering on December 12, 1980, offering 4.6 million shares at $22.00 per share ($0.10 split-adjusted). [Interpretation] The company has executed five stock splits (2-for-1 in 1987, 2000, 2005; 7-for-1 in 2014; 4-for-1 in 2020), transitioning from a speculative microcomputer manufacturer into the world's most valuable consumer platform."
    },
    "SECTION_15_SWOT": {
      "strengths": [
        "[Fact] Global active installed device footprint exceeding 2.2 billion units creating self-reinforcing network effects.",
        "[Fact] Industry-leading cash generation with over $100B in annual operating cash flows and net debt to EBITDA of 0.65x.",
        "[Judgment] Best-in-class brand loyalty and hardware-software vertical integration yielding high pricing power."
      ],
      "weaknesses": [
        "[Fact] High dependence on iPhone hardware, which continues to account for over 50% of consolidated net sales.",
        "[Fact] Elevated valuation multiples (PEG of 7.42) capping near-term upside.",
        "[Derived] Reinvestment rate tempered by market saturation in mature smartphone geographies."
      ],
      "opportunities": [
        "[Interpretation] Monetization of Apple Intelligence across the device refresh cycle triggering an accelerated upgrade supercycle.",
        "[Interpretation] Continuous high-margin Services growth across Payments, Cloud, Advertising, and App Subscriptions.",
        "[Estimate] Geographic expansion across emerging markets, specifically India and Southeast Asia."
      ],
      "threats": [
        "[Fact] Regulatory antitrust scrutiny targeting App Store fee structures and default search agreements (e.g., EU DMA and US DOJ litigation).",
        "[Fact] Concentrated hardware supply chain exposure centered in Greater China and Taiwan.",
        "[Interpretation] Geopolitical headwinds and domestic substitution risks in mainland China."
      ]
    },
